const CONSUMER_NAMESPACE = /^[a-z][a-z0-9]*(?:[.-][a-z0-9]+)*$/u;
const SCHEMA_KIND = /^[a-z][a-z0-9]*(?:[.-][a-z0-9]+)*$/u;
export class WorkflowNamespaceError extends TypeError {
    code;
    constructor(code, message) {
        super(message);
        this.name = 'WorkflowNamespaceError';
        this.code = code;
    }
}
export function createWorkflowNamespaceConfig(input) {
    if (!CONSUMER_NAMESPACE.test(input.consumerNamespace)) {
        throw new WorkflowNamespaceError('WORKFLOW_NAMESPACE_CONFIG_INVALID', 'Workflow namespace configuration is invalid.');
    }
    return Object.freeze({
        schemaVersion: 1,
        consumerNamespace: input.consumerNamespace,
    });
}
export function workflowSchemaId(kind, version) {
    if (!SCHEMA_KIND.test(kind) ||
        !Number.isSafeInteger(version) ||
        version < 1) {
        throw new WorkflowNamespaceError('WORKFLOW_SCHEMA_ID_INVALID', 'Workflow schema identity is invalid.');
    }
    return `workflow.${kind}.v${version}`;
}
export function createWorkflowRecordIdentity(config, kind, version) {
    const validated = createWorkflowNamespaceConfig(config);
    return Object.freeze({
        schema: workflowSchemaId(kind, version),
        consumerNamespace: validated.consumerNamespace,
    });
}
export function assertAllowedSignatureNamespace(recordNamespace, allowedNamespaces) {
    if (typeof recordNamespace === 'string' &&
        Array.isArray(allowedNamespaces) &&
        allowedNamespaces.includes(recordNamespace)) {
        return recordNamespace;
    }
    throw new WorkflowNamespaceError('WORKFLOW_SIGNATURE_NAMESPACE_UNSUPPORTED', 'Signed record namespace is not allowlisted.');
}
